        measure(|| cursor.grow::<Diagnostic>(function, 1, &mut budget))
    });
    assert!(result.is_err());
    assert!(!refused);
    assert_eq!(used, 0);
    assert_eq!(observed.allocated, 0);
    assert_eq!(cursor.frames.capacity(), 0);
}

